from google.cloud import kms_v1

from security_client import get_kms_client, resolve_kms_key_name
from security_models import SignVerifyRequest, SignVerifyResponse, normalize_ciphertext


def sign_or_verify_key(message: bytes, signature: Optional[bytes] = None, key_name: Optional[str] = None) -> Dict[str, Any]:
    client = kms_v1.KeyManagementServiceClient()
    key_name = resolve_kms_key_name(key_name)
    if signature is None:
        digest = kms_v1.Digest(sha256=message)
        response = client.asymmetric_sign(name=key_name, digest=digest)
        return SignVerifyResponse(key_name=key_name, signature=normalize_ciphertext(response.signature), verified=True, provider="google-cloud-kms").to_dict()
    response = client.asymmetric_verify(name=key_name, digest=kms_v1.Digest(sha256=message), signature=signature)
    return SignVerifyResponse(key_name=key_name, signature=normalize_ciphertext(signature), verified=response.verified, provider="google-cloud-kms").to_dict()


if __name__ == "__main__":
    message = os.environ.get("MESSAGE", "").encode("utf-8")
    signature = os.environ.get("SIGNATURE")
    key_name = os.environ.get("KMS_KEY_NAME")
    sig_bytes = signature.encode("utf-8") if signature else None
    print(sign_or_verify_key(message, signature=sig_bytes, key_name=key_name))
