from google.cloud import kms_v1

DEFAULT_PROVIDER = "google-cloud-kms"


@lru_cache(maxsize=1)
def get_kms_client() -> kms_v1.KeyManagementServiceClient:
    return kms_v1.KeyManagementServiceClient()


def resolve_kms_key_name(key_name: Optional[str] = None) -> str:
    value = key_name or os.environ.get("KMS_KEY_NAME") or os.environ.get("GOOGLE_CLOUD_KMS_KEY_NAME")
    if not value:
        raise ValueError("Missing Google Cloud KMS key name")
    return value


def resolve_project_id(project_id: Optional[str] = None) -> str:
    value = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCP_PROJECT")
    if not value:
        raise ValueError("Missing Google Cloud project id")
    return value
