from typing import Any, Dict, List

from google.cloud import logging_v2

from security_client import resolve_project_id


def key_usage_summary(project_id: str = None, limit: int = 50) -> Dict[str, Any]:
    project_id = resolve_project_id(project_id)
    client = logging_v2.Client(project=project_id)
    entries: List[Dict[str, Any]] = []
    for entry in client.list_entries(page_size=limit, filter_='resource.type="cloudkms_keyring"'):
        entries.append({"log_name": entry.log_name, "timestamp": str(entry.timestamp), "payload": str(entry.payload)})
    return {"project_id": project_id, "provider": "google-cloud-logging", "events": entries, "count": len(entries)}


if __name__ == "__main__":
    print(key_usage_summary(os.environ.get("GOOGLE_CLOUD_PROJECT")))
