from typing import Dict

from google.cloud import language_v1

from security_models import normalize_ciphertext


def payload_safety(decrypted_text: str) -> Dict[str, object]:
    client = language_v1.LanguageServiceClient()
    document = language_v1.Document(content=normalize_ciphertext(decrypted_text), type_=language_v1.Document.Type.PLAIN_TEXT)
    sentiment = client.analyze_sentiment(request={"document": document})
    unsafe = sentiment.document_sentiment.score < -0.5
    return {"provider": "google-cloud-language", "unsafe": unsafe, "score": sentiment.document_sentiment.score}


if __name__ == "__main__":
    print(payload_safety(os.environ.get("DECRYPTED_TEXT", "")))
