from typing import Dict

from google.cloud import translate_v3

from security_client import resolve_project_id


def compliance_note_translate(text: str, target_language_code: str = "en", project_id: str = None, location: str = "global") -> Dict[str, object]:
    project_id = resolve_project_id(project_id)
    client = translate_v3.TranslationServiceClient()
    parent = f"projects/{project_id}/locations/{location}"
    response = client.translate_text(request={"parent": parent, "contents": [text], "target_language_code": target_language_code})
    translations = [item.translated_text for item in response.translations]
    return {"provider": "google-cloud-translate", "translations": translations, "target_language_code": target_language_code}


if __name__ == "__main__":
    print(compliance_note_translate(os.environ.get("NOTE_TEXT", "encryption compliance note"), os.environ.get("TARGET_LANGUAGE", "en")))}
